# ДОКУМЕНТ: zavod/ops/operator/cmd_b12_r2_pb1trial2_v0_1.sh — команда оператора: ВТОРОЙ R2 (печать остатка pb1trial2)
#   программой R2 из выпуска B12 (шаг 3.5.5 ПБ-1, пункт 6 проекта B12 v0.3.1)
# ВЕРСИЯ: v0.1  СТАТУС: DRAFT (не выдавать оператору до независимого аудита этой команды, приёмки итога установки B12
#   и «да» оператора)
# ДАТА СОЗДАНИЯ: 2026-11-18 07:18 +02:00  ИСПОЛНИТЕЛЬ: Claude (терминал zavod, пускатель)
# ОСНОВА: вход — как cmd_b12_install_v0_1.sh (REL117 AGREED): env -i до bash, -q первым у программы скачивания, пределы,
#   новая папка 0700, сверка скачанного файла выпуска перед запуском. Тело R2 — как CMD_B11_R2_SEAL_PB1TRIAL2 v0.1
#   (REL104 AGREED), но программа R2 — /usr/local/lib/zavod/probes-b12/zprobe_r2.py (v0.10, REL111), проверка B8–B12 —
#   режимом verify-installed файла выпуска B12, вывод R2 — в новый файл ВНУТРИ новой папки скачивания.
# ПОРЯДОК: 1) скачать файл выпуска B12 в новую папку и сверить (как v0.1); 2) папка пакета есть; 3) verify-installed B12
#   (B8–B11 целы, цели B12 по INSTALLED.sha256: TARGETS_SAME, INSTALLED_LIST) — иначе STOP, R2 не запускается;
#   4) zprobe_r2.py в probes-b12 — обычный файл root:root 0644, одна ссылка, SHA-256 = принятой REL111 (bb7ce5f4…) — иначе
#   STOP; 5) R2 из пустого окружения (только PATH закреплён: проверки вызывают journalctl) — вывод в новый файл
#   $D/zprobe-r2-b12-pb1trial2.out; на экран: путь, размер, SHA-256 и код, затем строки вывода: строка R2_DIAG — ЦЕЛИКОМ
#   (ради неё и делался B12), остальные — первые 240 знаков (R2_OBS целиком — в файле и в файле наблюдений).
#   6) Итог: код 0 и строка R2=… status=SAFE_PRE_START — «CMD_DONE R2 SAFE_PRE_START»; иначе STOP: НЕ повторять.
# ЧТО МЕНЯЕТ НА СЕРВЕРЕ: новая папка скачивания в /root с файлом выпуска и файлом вывода; сам R2 — новый файл наблюдений в
#   /var/lib/zavod/r2obs/pb1trial2, при SAFE_PRE_START — печать (снимок в seal, proof.json, запись печати), как в B11.
# НЕ ДЕЛАЕТ: не ставит и не меняет программы, не запускает пробу, серию и службы; B8–B12, /root/zprobe2 не меняет;
#   ничего не удаляет, не переименовывает, не перезаписывает; номер аренды не печатает. Сервер до R2 не перезагружать.
# Оператор вставляет ПОСЛЕДНЮЮ строку файла целиком в сессию root@zavod-1. Испытание: CI zavod-probes-3-5-5 v0.40,
#   задание b12-r2-cmd.
/usr/bin/env -i /bin/bash --norc --noprofile -c 'set -eu -o pipefail -o noclobber; umask 077; PATH=/usr/sbin:/usr/bin:/sbin:/bin; export PATH; SAID=; die() { SAID=1; echo "$1"; exit 1; }; fin() { r=$?; [ "$r" = 0 ] || [ -n "$SAID" ] || echo "STOP: unexpected error (code $r); nothing more run"; }; trap fin EXIT; [ "$(id -u)" = 0 ] || die "REFUSED: run as root; nothing done"; S=90c019439d9636186d7860b549e67931b0533264ae0a6acc0cbb640e3f66c176; N=601832; P=/var/lib/zavod/probes-pkg-20ae4a839adc; U=https://raw.githubusercontent.com/bereznyi-aleksandr/ai-devops-system/1d4d2caf62e0824c36ff46596059ed8e5ae01fe1/zavod/ops/server/probes/zprobe-release-3.5.5-b12.sh; anc() { d=$1; while :; do [ -d "$d" ] && [ ! -L "$d" ] && [ "$(stat -c %u "$d")" = 0 ] && [ -z "$(find "$d" -maxdepth 0 -perm /022)" ] || return 1; [ "$d" = / ] && return 0; d=$(dirname "$d"); done; }; anc /root || die "REFUSED: /root or / is not a root-only plain folder; nothing done"; D=/root/zprobe-b12-r2-1d4d2caf62e0-$(date -u +%Y%m%dT%H%M%SZ)-$$; mkdir -m 0700 "$D" || die "REFUSED: cannot create new folder $D; nothing done"; F=$D/zprobe-release-3.5.5-b12.sh; curl -q -fsSL --proto =https --proto-redir =https --tlsv1.2 --connect-timeout 30 --max-time 300 --max-filesize "$N" "$U" | head -c "$((N + 1))" > "$F" || die "REFUSED: download into new $F failed or exceeded limits; $D kept as evidence, nothing run"; ok() { anc "$D" && [ -f "$F" ] && [ ! -L "$F" ] && [ "$(stat -c %u:%g:%h:%s "$F")" = "0:0:1:$N" ] && [ -z "$(find "$F" -maxdepth 0 -perm /022)" ] && [ "$(sha256sum < "$F" | cut -d" " -f1)" = "$S" ]; }; ok || die "REFUSED: $F type, owner, links, size or sum differs; kept as evidence, nothing run"; echo "FILE_OK $F size=$N sha256=$S"; { [ -d "$P" ] && [ ! -L "$P" ]; } || die "STOP: $P is missing or not a plain folder; R2 not run"; anc /var/lib/zavod || die "STOP: /var/lib/zavod or a parent folder is not root-only; R2 not run"; run() { ok || die "STOP: $F changed before $*; R2 not run"; rc=0; O=$(/usr/bin/env -i /bin/bash --norc --noprofile "$F" "$@" 2>&1) || rc=$?; printf "%s\n" "$O"; echo "RC $* = $rc"; }; bad() { printf "%s\n" "$O" | grep -Eq "^CHECK [^ ]+ (FAIL|WAIT) "; }; run verify-installed; { [ "$rc" = 0 ] && printf "%s\n" "$O" | grep -qxF "ZPROBE_B12_VERIFY_INSTALLED=OK fails=0" && printf "%s\n" "$O" | grep -qxF "CHECK TARGETS_SAME OK -" && printf "%s\n" "$O" | grep -q "^CHECK INSTALLED_LIST OK " && ! bad; } || die "STOP after verify-installed (B8-B12 not intact, FAIL, WAIT or unknown result); R2 not run"; L=/usr/local/lib/zavod/probes-b12; R=$L/zprobe_r2.py; RS=bb7ce5f49fdb32de995cad3c475556e0aad80511fc2ebf46bfa2aeca774e8ee9; { anc "$L" && [ -f "$R" ] && [ ! -L "$R" ] && [ "$(stat -c %u:%g:%h:%a "$R")" = "0:0:1:644" ] && [ "$(sha256sum < "$R" | cut -d" " -f1)" = "$RS" ]; } || die "STOP: $R is not the accepted R2 program (folder, owner, links, mode or sum); R2 not run"; echo "R2_PROGRAM_OK $R sha256=$RS"; X=$D/zprobe-r2-b12-pb1trial2.out; r=0; /usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin /usr/bin/python3 -I -B "$R" pb1trial2 > "$X" 2>&1 || r=$?; echo "R2_OUT=$X size=$(stat -c %s "$X") sha256=$(sha256sum < "$X" | cut -d" " -f1) rc=$r"; while IFS= read -r x || [ -n "$x" ]; do case "$x" in "R2_DIAG "*) printf "%s\n" "$x";; *) printf "%s\n" "${x:0:240}";; esac; done < "$X"; { [ "$r" = 0 ] && grep -Eq "^R2=[^ ]+ status=SAFE_PRE_START( |$)" "$X"; } || die "STOP: R2 rc=$r, not SAFE_PRE_START; do not repeat; send the whole output"; echo "CMD_DONE R2 SAFE_PRE_START"'
